-- Seed: generic OBD-II DTC definitions + 20 SAMPLE confirmed fixes.
-- SAMPLE rows are synthetic illustrations of the data shape. They are labeled SAMPLE
-- everywhere in the UI and must never be presented as verified repair information.

-- ---------------------------------------------------------------- DTC definitions (SAE J2012 generic)
on conflict (code) do update set description = excluded.description, system = excluded.system, category = excluded.category, common_causes = excluded.common_causes, safety_flag = excluded.safety_flag;

-- ---------------------------------------------------------------- 20 SAMPLE fixes
-- Part numbers below are placeholders ("SAMPLE-…"), not real catalog numbers.
begin;
create temp table seed_fix (
  key text primary key, title text, year int, make text, model text, engine text, mileage int,
  symptoms text, freeze_frame text, tests jsonb, root_cause text, fix text, labor numeric,
  codes text[], parts jsonb, up int, down int
) on commit drop;

-- 2015 F-150 5.0
('f150_1','Cold-start rattle and P0016/P0017 - worn VCT phasers', 2015,'Ford','F-150','5.0L V8', 88000,
