with ins as (
                            root_cause, fix_description, labor_hours, status, source_label, seed_confirm_count, seed_deny_count,
                            confirm_count, deny_count, net_score, verified_at)
  select md5('sample:' || key)::uuid, null, title, year, make, model, engine, mileage, symptoms, freeze_frame, tests,
         root_cause, fix, labor, 'approved', 'SAMPLE', up, down, up, down, up - down, case when up - down >= 3 then now() end
    from seed_fix
  on conflict (id) do update set title = excluded.title, symptoms = excluded.symptoms, root_cause = excluded.root_cause,
         fix_description = excluded.fix_description, tests_performed = excluded.tests_performed
  returning id
)
select count(*) from ins;

select md5('sample:' || s.key)::uuid, c from seed_fix s, unnest(s.codes) c
on conflict do nothing;

delete from public.fix_parts where fix_id in (select md5('sample:' || key)::uuid from seed_fix);
select md5('sample:' || s.key)::uuid, p ->> 'name', p ->> 'part_number', (p ->> 'quantity')::numeric, (p ->> 'unit_price')::numeric, ord - 1
  from seed_fix s, jsonb_array_elements(s.parts) with ordinality as t(p, ord);
commit;
